    // Build descriptive alt text for product images: "Name, Type, Volume"
    // Uses p.name (brand + product) and p.description (type · volume).
    // Replaces the middle-dot separator so it reads naturally as spoken text.
    function productAltText(p) {
        const name = (p.name || '').trim();
        const desc = (p.description || '').trim().replace(/\s*·\s*/g, ', ');
        return desc ? `${name}, ${desc}` : name;
    }

    // Category → background gradient mapping
    function getGradient(category) {
        const c = (category || '').toLowerCase();
        if (c.includes('tequila'))                                                              return 'linear-gradient(135deg,#1a3a8f,#2a5fa3,#1e4aad)';
        if (c.includes('cognac') || c.includes('brandy'))                                      return 'linear-gradient(135deg,#291700,#5a3600,#8a5800)';
        if (c.includes('bourbon') || c.includes('whiskey') || c.includes('whisky') || c.includes('scotch')) return 'linear-gradient(135deg,#181818,#303030,#202020)';
        if (c.includes('white wine') || c.includes('sauvignon') || c.includes('chardonnay'))   return 'linear-gradient(135deg,#1a3c1a,#2a6028,#3a8040)';
        if (c.includes('wine') || c.includes('rosé') || c.includes('rose'))                    return 'linear-gradient(135deg,#180820,#46133a,#891f52)';
        if (c.includes('beer'))                                                                 return 'linear-gradient(135deg,#001840,#002a66,#00347c)';
        if (c.includes('vodka'))                                                                return 'linear-gradient(135deg,#1a1a2e,#2a2a4e,#16213e)';
        if (c.includes('gin'))                                                                  return 'linear-gradient(135deg,#0d3320,#1a5a38,#2a7a50)';
        if (c.includes('rum'))                                                                  return 'linear-gradient(135deg,#2d1400,#5c2800,#8a3d00)';
        return 'linear-gradient(135deg,#1a3a8f,#2a5fa3,#1e4aad)';
    }

    // Stock quantity indicator
    function stockHtml(stock) {
        if (stock === '' || stock === undefined || stock === null) return '';
        const n = parseInt(stock, 10);
        if (isNaN(n)) return '';
        if (n === 0) return '<div class="prod-stock out-stock">Out of stock</div>';
        if (n <= 5)  return `<div class="prod-stock low-stock">${n} left — order soon</div>`;
        return `<div class="prod-stock in-stock">${n} in stock</div>`;
    }

    // Escape HTML to prevent XSS from sheet data
    function esc(s) {
        return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

    let renderedProducts = [];

    // Star rating HTML
    function starsHtml(rating) {
        if (!rating) return '';
        const r = Math.min(5, Math.max(0, parseFloat(rating) || 0));
        if (!r) return '';
        const full  = Math.floor(r);
        const half  = (r - full) >= 0.5 ? 1 : 0;
        const empty = 5 - full - half;
        return `<div class="stars-row">
            ${'<span class="star full">★</span>'.repeat(full)}
            ${half ? '<span class="star half">★</span>' : ''}
            ${'<span class="star empty">★</span>'.repeat(empty)}
            <span class="rating-num">${r.toFixed(1)} / 5</span>
        </div>`;
    }

    function priceHtml(p, large) {
        const regular = parseFloat(p.price || 0).toFixed(2);
        const sale = p['sale price'] ? parseFloat(p['sale price']).toFixed(2) : null;
        const unit = `<span class="price-unit">/${esc(p.unit || 'btl')}</span>`;
        if (sale) {
            return `<div class="prod-price"><span class="price-orig">$${regular}</span> <span class="price-sale">$${sale}</span> ${unit}</div>`;
        }
        return `<div class="prod-price">$${regular} ${unit}</div>`;
    }

    // Open product detail modal
    let _modalTrigger = null;
    function openModal(index, triggerEl) {
        const p = renderedProducts[index];
        if (!p) return;
        _modalTrigger = triggerEl || document.activeElement;
        document.getElementById('modal-inner').innerHTML = `
            <div class="modal-img-panel" style="background:${getGradient(p.category)}">
                ${(p.image || PRODUCT_IMAGES[p.name])
                    ? `<img src="${esc(p.image || PRODUCT_IMAGES[p.name])}" alt="${esc(productAltText(p))}" loading="lazy">`
                    : `<span class="modal-art" aria-hidden="true">${esc(p.emoji || '🍾')}</span>`}
                ${p.badge ? `<span class="prod-badge" aria-hidden="true">${esc(p.badge)}</span>` : ''}
            </div>
            <div class="modal-info">
                <div class="modal-cat">${esc(p.category)}</div>
                <h2 class="modal-name" id="modal-title">${esc(p.name)}</h2>
                ${starsHtml(p.rating)}
                <p class="modal-desc">${esc(p.description) || 'No description available.'}</p>
                <hr class="modal-divider">
                <div class="modal-price-row">
                    ${priceHtml(p)}
                    ${stockHtml(p.stock)}
                </div>
                <p class="modal-price-note">Price may not be accurate. Please call to confirm the current price and availability.</p>
                <a href="tel:${PHONE}" class="modal-call-btn"><span aria-hidden="true">📞</span> Call to Order</a>
            </div>
        `;
        const overlay = document.getElementById('modal-overlay');
        overlay.classList.add('open');
        document.body.style.overflow = 'hidden';
        // move focus to the close button
        const closeBtn = overlay.querySelector('.modal-close');
        if (closeBtn) setTimeout(() => closeBtn.focus(), 50);
        // focus trap
        overlay.addEventListener('keydown', trapFocus);
    }

    function closeModal() {
        const overlay = document.getElementById('modal-overlay');
        overlay.classList.remove('open');
        overlay.removeEventListener('keydown', trapFocus);
        document.body.style.overflow = '';
        if (_modalTrigger && _modalTrigger.focus) _modalTrigger.focus();
        _modalTrigger = null;
    }

    function trapFocus(e) {
        if (e.key !== 'Tab') return;
        const modal = document.querySelector('.modal');
        const focusable = modal.querySelectorAll('a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])');
        const first = focusable[0];
        const last  = focusable[focusable.length - 1];
        if (e.shiftKey) {
            if (document.activeElement === first) { e.preventDefault(); last.focus(); }
        } else {
            if (document.activeElement === last)  { e.preventDefault(); first.focus(); }
        }
    }

    // Build and inject product cards into the grid
    function renderProducts(products) {
        renderedProducts = products;
        const grid = document.getElementById('prod-grid');
        if (!products.length) {
            grid.innerHTML = '<p class="prod-empty">No products found. Check your Google Sheet setup.</p>';
            return;
        }
        grid.innerHTML = products.map((p, i) => `
            <div class="prod-card reveal" onclick="openModal(${i},this)" role="button" tabindex="0"
                 aria-label="View details for ${esc(p.name)}">
                <div class="prod-img" style="background:${getGradient(p.category)}">
                    ${(p.image || PRODUCT_IMAGES[p.name]) ? `<img src="${esc(p.image || PRODUCT_IMAGES[p.name])}" alt="${esc(productAltText(p))}" loading="lazy">` : `<span class="prod-art" aria-hidden="true">${esc(p.emoji || '🍾')}</span>`}
                    ${p.badge ? `<span class="prod-badge">${esc(p.badge)}</span>` : ''}
                </div>
                <div class="prod-body">
                    <div class="prod-cat">${esc(p.category)}</div>
                    <div class="prod-name">${esc(p.name)}</div>
                    ${priceHtml(p)}
                    <div class="prod-view">View Details →</div>
                </div>
            </div>
        `).join('');
        if (revealObserver) {
            grid.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));
        }
    }

    // Minimal CSV parser — handles quoted fields with commas inside
    function parseCSVRow(line) {
        const result = []; let cur = '', inQ = false;
        for (const ch of line) {
            if (ch === '"') { inQ = !inQ; continue; }
            if (ch === ',' && !inQ) { result.push(cur); cur = ''; continue; }
            cur += ch;
        }
        result.push(cur);
        return result;
    }
    function parseCSV(text) {
        const lines = text.split('\n').map(l => l.trimEnd()).filter(Boolean);
        if (lines.length < 2) return [];
        const headers = parseCSVRow(lines[0]).map(h => h.trim().toLowerCase());
        return lines.slice(1).map(line => {
            const vals = parseCSVRow(line);
            const obj = {};
            headers.forEach((h, i) => { obj[h] = (vals[i] || '').trim(); });
            return obj;
        }).filter(p => p.name);
    }

    // Fetch products from Google Sheet, fall back silently to defaults
    async function loadFromSheet() {
        if (!SHEET_CSV_URL) return;
        try {
            const res = await fetch(SHEET_CSV_URL + '&t=' + Date.now(), { cache: 'no-store' });
            if (!res.ok) throw new Error('HTTP ' + res.status);
            const products = parseCSV(await res.text());
            if (products.length) { allProducts = products; applyFilter(); }
        } catch (e) {
            console.warn("[CJ's Liquors] Could not load Google Sheet:", e.message);
        }
    }

    // ── SEARCH & FILTERING ───────────────────────────────────────────
    let allProducts  = [];
    let activeFilter = null;
    let searchQuery  = '';
    let searchTimer  = null;

    function _syncSearchUI(val) {
        ['search-input', 'nav-search-input', 'nav-search-mobile'].forEach(id => {
            const el = document.getElementById(id);
            if (el && el.value !== val) el.value = val;
        });
        ['search-clear', 'nav-search-x', 'nav-search-x-mob'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.classList.toggle('visible', val.length > 0);
        });
    }

    function onSearch(val) {
        clearTimeout(searchTimer);
        searchTimer = setTimeout(() => {
            searchQuery = val.trim();
            _syncSearchUI(searchQuery);
            applyFilter();
        }, 180);
    }

    function clearSearch() {
        clearTimeout(searchTimer);
        searchQuery = '';
        _syncSearchUI('');
        applyFilter();
    }

    function matchesSearch(p, q) {
        const lower = q.toLowerCase();
        return (p.name        || '').toLowerCase().includes(lower) ||
               (p.category    || '').toLowerCase().includes(lower) ||
               (p.description || '').toLowerCase().includes(lower) ||
               (p.badge       || '').toLowerCase().includes(lower);
    }

    const CATEGORY_GROUPS = {
        wine:    ['wine', 'rosé', 'rose', 'champagne', 'sparkling', 'sauvignon', 'chardonnay', 'merlot', 'pinot', 'cava', 'prosecco', 'riesling', 'moscato'],
        spirits: ['tequila', 'mezcal', 'whiskey', 'whisky', 'scotch', 'bourbon', 'cognac', 'brandy', 'vodka', 'gin', 'rum', 'spirits', 'liqueur', 'schnapps'],
        beer:    ['beer', 'ale', 'lager', 'ipa', 'stout', 'porter', 'pilsner', 'bock', 'sour', 'craft', 'cider'],
        sale:    [], // matched via badge field
        new:     [], // matched via badge field
    };

    function matchesFilter(product, group) {
        if (group === 'sale') return (product.badge || '').toLowerCase().includes('sale');
        if (group === 'new')  return (product.badge || '').toLowerCase().includes('new');
        const c = (product.category || '').toLowerCase();
        return (CATEGORY_GROUPS[group] || []).some(k => c.includes(k));
    }

    function filterByCategory(group) {
        activeFilter = group;
        applyFilter();
    }

    function clearFilter() {
        activeFilter = null;
        applyFilter();
    }

    function applyFilter() {
        const bar   = document.getElementById('filter-bar');
        const label = document.getElementById('filter-label-text');

        let filtered = activeFilter
            ? allProducts.filter(p => matchesFilter(p, activeFilter))
            : allProducts;

        if (searchQuery) {
            filtered = filtered.filter(p => matchesSearch(p, searchQuery));
        }

        if (activeFilter && bar && label) {
            const names = { wine: 'Wine', spirits: 'Spirits', beer: 'Beer', sale: 'On Sale', new: 'New Arrivals' };
            label.textContent = names[activeFilter] || activeFilter;
            bar.classList.add('visible');
        } else if (bar) {
            bar.classList.remove('visible');
        }

        if (!filtered.length && (activeFilter || searchQuery)) {
            document.getElementById('prod-grid').innerHTML =
                `<div class="no-results"><strong>No products found</strong>Try a different search or <button class="filter-clear" style="display:inline-flex" onclick="clearSearch();clearFilter()">clear all filters</button></div>`;
        } else {
            renderProducts(filtered);
        }
    }

    // ── MODAL KEYBOARD SUPPORT ───────────────────────────────────────
    document.addEventListener('keydown', e => {
        if (e.key === 'Escape') closeModal();
    });
    document.addEventListener('keydown', e => {
        if ((e.key === 'Enter' || e.key === ' ') && e.target.classList.contains('prod-card')) {
            e.preventDefault();
            e.target.click();
        }
    });

    // ── INIT ─────────────────────────────────────────────────────────
    // Deep links from the rest of the site: shop.html?cat=wine  /  shop.html?q=bourbon
    const _params = new URLSearchParams(window.location.search);
    const _cat = (_params.get('cat') || '').toLowerCase();
    if (_cat && Object.prototype.hasOwnProperty.call(CATEGORY_GROUPS, _cat)) activeFilter = _cat;
    const _q = (_params.get('q') || '').trim();
    if (_q) { searchQuery = _q; _syncSearchUI(_q); }

    allProducts = DEFAULT_PRODUCTS;
    applyFilter();          // show defaults immediately
    loadFromSheet();        // then replace with sheet data if available
